    </section>

    <section class="collection" id="collection">
      <div class="collection-head">
        <h2>The Genesis Run</h2>
        <p>Four metals · one questionable economy</p>
      </div>
      <div class="grid">
        <div class="edition" data-edition="bronze" data-state="available">
          <canvas class="edition-canvas" aria-label="Bronze edition coin"></canvas>
          <h3>Bronze</h3>
