        <div class="edition" data-edition="silver" data-state="available">
          <canvas class="edition-canvas" aria-label="Silver edition coin"></canvas>
          <h3>Silver</h3>
          <div class="meta">5,000 Tokens · Proof frost</div>
          <div class="status">Available now</div>
          <button class="buy">Add to cart</button>
        </div>
        <div class="edition" data-edition="gold" data-state="sold-out">
