  <footer>© 2026 WastedToken Mint · Absolutely no financial advice was harmed in this production.</footer>

  <script>
  (() => {
    const palettes = {
      hero:   {base:"#b77b31", dark:"#3a200b", light:"#ffe39a", edge:"#8c541e", ink:"#241306"},
      bronze: {base:"#a65e31", dark:"#3e1c10", light:"#efaf68", edge:"#6c351c", ink:"#281209"},
      silver: {base:"#aeb9bd", dark:"#3d5159", light:"#f8ffff", edge:"#7f9299", ink:"#17242a"},
      gold:   {base:"#d6a42d", dark:"#654312", light:"#fff1a0", edge:"#9b7019", ink:"#3d2708"},
      black:  {base:"#27323a", dark:"#070a0c", light:"#c9e7df", edge:"#131a20", ink:"#020304"}
    };

    function fit(canvas) {
      const r = canvas.getBoundingClientRect(), d = Math.min(devicePixelRatio || 1, 2);
      const w = Math.max(1, Math.round(r.width*d)), h = Math.max(1, Math.round(r.height*d));
      if (canvas.width !== w || canvas.height !== h) { canvas.width=w; canvas.height=h; }
      return {w,h,d};
    }
    function hexAlpha(hex, alpha) {
      const n = parseInt(hex.slice(1),16);
      return `rgba(${n>>16},${(n>>8)&255},${n&255},${alpha})`;
    }
    function circlePath(ctx, ox, oy, ux, uy, vx, vy) {
      ctx.beginPath();
      for(let i=0;i<=96;i++){
        const q=i/96*Math.PI*2, x=ox+ux*Math.cos(q)+vx*Math.sin(q), y=oy+uy*Math.cos(q)+vy*Math.sin(q);
        i?ctx.lineTo(x,y):ctx.moveTo(x,y);
      }
      ctx.closePath();
    }
    function textOnFace(ctx, label, pal, back, size) {
      ctx.save();
      ctx.clip();
      const grad=ctx.createRadialGradient(-.22,-.3,.05,.05,.08,1.25);
      grad.addColorStop(0,pal.light); grad.addColorStop(.20,pal.base); grad.addColorStop(.72,pal.base); grad.addColorStop(1,pal.dark);
      ctx.fillStyle=grad;ctx.fillRect(-1,-1,2,2);
      ctx.lineWidth=.035;ctx.strokeStyle=hexAlpha(pal.light,.7);ctx.beginPath();ctx.arc(0,0,.89,0,Math.PI*2);ctx.stroke();
      ctx.lineWidth=.018;ctx.strokeStyle=hexAlpha(pal.ink,.9);ctx.beginPath();ctx.arc(0,0,.79,0,Math.PI*2);ctx.stroke();

      ctx.strokeStyle=hexAlpha(pal.light,.5);ctx.lineWidth=.012;
      for(let i=0;i<34;i++){let a=i*Math.PI*2/34;ctx.beginPath();ctx.moveTo(.79*Math.cos(a),.79*Math.sin(a));ctx.lineTo(.85*Math.cos(a),.85*Math.sin(a));ctx.stroke()}
      ctx.fillStyle=pal.ink;ctx.globalAlpha=.88;
      ctx.font=`bold ${size*.105}px Georgia`;ctx.textAlign="center";ctx.textBaseline="middle";
      if(back) {
        ctx.fillText("10,000",0,-.11);ctx.font=`bold ${size*.042}px Arial`;ctx.letterSpacing=".08em";ctx.fillText("TOKENS",0,.12);
        ctx.font=`${size*.027}px Arial`;ctx.fillText("WASTEDTOKEN MINT",0,.47);
        ctx.beginPath();ctx.arc(0,-.1,.42,0,Math.PI*2);ctx.strokeStyle=hexAlpha(pal.light,.42);ctx.lineWidth=.018;ctx.stroke();
      } else {
        // raised emblem: offset dark shadow, then bright metal crown and W
        ctx.save();ctx.translate(.025,.032);ctx.fillStyle=hexAlpha(pal.dark,.92);
        ctx.font=`bold ${size*.32}px Georgia`;ctx.fillText("W",0,.08);ctx.restore();
        ctx.font=`bold ${size*.32}px Georgia`;ctx.fillStyle=pal.light;ctx.fillText("W",0,.045);
        ctx.strokeStyle=hexAlpha(pal.ink,.9);ctx.lineWidth=.016;ctx.beginPath();ctx.arc(0,.01,.40,0,Math.PI*2);ctx.stroke();
        ctx.font=`bold ${size*.039}px Arial`;ctx.fillStyle=pal.ink;ctx.fillText("WASTEDTOKEN",0,.49);
        ctx.font=`${size*.029}px Arial`;ctx.fillText("MINT · PROOF OF PRESENCE",0,-.50);
      }
      ctx.restore();
    }
    function drawCoin(canvas, t, kind="hero", staticAngle) {
      const {w,h}=fit(canvas), ctx=canvas.getContext("2d"), pal=palettes[kind];
      ctx.clearRect(0,0,w,h); ctx.fillStyle="#061015";ctx.fillRect(0,0,w,h);
      const cx=w/2,cy=h/2, R=Math.min(w*.285,h*.365), thick=R*.18;
      let a,b;
      if(staticAngle !== undefined){a=staticAngle; b=.20;}
      else { a=t*Math.PI*2; b=t*Math.PI*2+.42; }
      // Basis of the coin face after 3D rotations about vertical and horizontal axes.
      const ux=Math.cos(a), uy=0;
      const vx=Math.sin(a)*Math.sin(b), vy=Math.cos(b);
      const nx=Math.sin(a)*Math.cos(b), ny=-Math.sin(b), nz=Math.cos(a)*Math.cos(b);
      const frontX=cx+nx*thick/2, frontY=cy+ny*thick/2;
      const backX=cx-nx*thick/2, backY=cy-ny*thick/2;
      const nearIsFront=nz>=0, nearX=nearIsFront?frontX:backX, nearY=nearIsFront?frontY:backY;
      const farX=nearIsFront?backX:frontX, farY=nearIsFront?backY:frontY;

      // Far face gives the cylinder real depth at edge-on moments.
      circlePath(ctx,farX,farY,ux*R,uy*R,vx*R,vy*R);
      ctx.fillStyle=pal.dark;ctx.fill();

      // The reeded rim: individual alternating metal teeth bridge both faces.
      for(let i=0;i<88;i++){
        const q=i*Math.PI*2/88, c=Math.cos(q),s=Math.sin(q);
        const x1=frontX+(ux*c+vx*s)*R, y1=frontY+(uy*c+vy*s)*R;
        const x2=backX +(ux*c+vx*s)*R, y2=backY +(uy*c+vy*s)*R;
        ctx.strokeStyle=i%2?pal.edge:pal.light;ctx.globalAlpha=i%2?.82:.54;
        ctx.lineWidth=Math.max(1,R*.024);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();
      }
      ctx.globalAlpha=1;
      circlePath(ctx,nearX,nearY,ux*R,uy*R,vx*R,vy*R);
      ctx.fillStyle=pal.base;ctx.fill();

      // Face artwork in a true transformed disc coordinate system.
      ctx.save();
      ctx.translate(nearX,nearY);ctx.transform(ux*R,uy*R,vx*R,vy*R,0,0);
      textOnFace(ctx,"",pal,!nearIsFront,R);

      // Moving specular rake, intentionally tied to spin orientation.
      ctx.save();ctx.clip();
      const hx=Math.sin(a*1.15+b*.38)*1.25, hy=Math.cos(a*.72-b)*.52;
      const g=ctx.createRadialGradient(hx,hy,0,hx,hy,.68);
      g.addColorStop(0,"rgba(255,255,245,.92)");
      g.addColorStop(.15,"rgba(255,255,230,.42)");
      g.addColorStop(.48,"rgba(255,255,255,.08)");
      g.addColorStop(1,"rgba(255,255,255,0)");
      ctx.fillStyle=g;ctx.fillRect(-1,-1,2,2);
      ctx.restore();
      ctx.restore();

      // Crisp nearest rim catches light separately from face.
      circlePath(ctx,nearX,nearY,ux*R*.905,uy*R*.905,vx*R*.905,vy*R*.905);
      ctx.strokeStyle=hexAlpha(pal.light,.45);ctx.lineWidth=Math.max(1,R*.015);ctx.stroke();
    }

    const hero=document.getElementById("coin-hero");
    let paused=false, current=0, started=performance.now(), frame;
    function render(t){current=((t%1)+1)%1;drawCoin(hero,current,"hero")}
    function loop(now){if(!paused){render((now-started)/7000);frame=requestAnimationFrame(loop)}}
    window.addEventListener("resize",()=>render(current));
    frame=requestAnimationFrame(loop);
    window.demo={
      canvas:hero,
      setTime(t){paused=true;cancelAnimationFrame(frame);render(Number(t));},
      pause(){paused=true;cancelAnimationFrame(frame);}
    };

    const angles={bronze:-.58,silver:.42,gold:1.08,black:-1.02};
    document.querySelectorAll(".edition").forEach(tile=>{
      const c=tile.querySelector("canvas"), name=tile.dataset.edition;
      const paint=()=>drawCoin(c,.18,name,angles[name]);
      paint(); window.addEventListener("resize",paint);
    });
  })();
  </script>
</body>
</html>
